function StoryboardDayPanel({ day, today, displayUnit, weekHasSessions, blockId, weekIndex, onOpenSession, onAddSession }: { day: RoadmapWeek['days'][number]; today: string; displayUnit: DisplayWeightUnit; weekHasSessions: boolean; blockId: number | null; weekIndex: number; onOpenSession: (id?: number | null, context?: ProgrammingReturnContext) => void; onAddSession: (date: string) => void }) {
  const session = day.sessions[0] || null;
  if (!session) {
    const emptyState = storyboardEmptyDayState(day.date, today, weekHasSessions);
    const emptyColor = emptyState === 'gap' ? '#E0448D' : emptyState === 'open' ? colors.violet : colors.subtle;
    const title = emptyState === 'gap' ? 'Programming gap' : emptyState === 'open' ? 'Open target' : 'Rest';
    const detail = emptyState === 'gap' ? 'This future week still needs programming.' : emptyState === 'open' ? 'Build from a recent Session or start custom.' : 'No training is scheduled for this day.';
    return <View style={[storyStyles.emptyDayPanel, { borderColor: `${emptyColor}66` }]}><LinearGradient colors={[`${emptyColor}22`, '#0A0C11', '#07080C']} style={StyleSheet.absoluteFillObject} /><View style={[storyStyles.emptyStateMark, { borderColor: `${emptyColor}88` }]}><Ionicons name={emptyState === 'gap' ? 'alert-circle-outline' : emptyState === 'open' ? 'add' : 'moon-outline'} size={34} color={emptyColor} /></View><Text style={[storyStyles.emptyDayState, { color: emptyColor }]}>{emptyState === 'gap' ? 'ATTENTION' : emptyState === 'open' ? 'AVAILABLE' : 'RECOVERY'}</Text><Text style={storyStyles.emptyDayTitle}>{title}</Text><Text style={storyStyles.emptyDayMeta}>{detail}</Text>{emptyState !== 'rest' ? <SLButton label={emptyState === 'gap' ? '+ Program Session' : '+ Build Session'} onPress={() => day.date && onAddSession(day.date)} /> : null}</View>;
  }
  const completed = storyboardSessionState(session) === 'completed';
  const focus = storyboardSessionMuscleFocus(session);
  const duration = sessionDurationPresentation(session);
  return <View style={storyStyles.dayPanel}><View style={storyStyles.dayArtworkFrame}><LinearGradient colors={completed ? ['rgba(25,93,64,0.34)', 'rgba(29,15,45,0.38)', '#080A0F'] : ['rgba(111,73,14,0.35)', 'rgba(31,17,48,0.38)', '#080A0F']} end={{ x: 1, y: 1 }} style={StyleSheet.absoluteFillObject} /><View style={storyStyles.dayArtworkCopy}><Text style={[storyStyles.dayState, { color: storyboardSessionColor(session) }]}>{completed ? 'Completed' : sessionStatusText(session)}</Text><Text style={storyStyles.daySessionTitle}>{sessionTitle(session)}</Text><Text style={storyStyles.daySessionMeta}>{storyboardSessionEvidence(session, displayUnit)}</Text></View><View style={storyStyles.dayAnatomy}><StoryboardSessionArtwork session={session} /></View><View style={[storyStyles.dayFocusRail, { backgroundColor: storyboardSessionColor(session) }]} /></View><View style={storyStyles.focusLegend}><View style={storyStyles.focusLegendItem}><View style={[storyStyles.focusLegendDot, { backgroundColor: '#A865FF' }]} /><Text style={storyStyles.focusLegendText}>{focus.primary[0] ? storyboardMuscleLabel(focus.primary[0]) : 'Primary focus'}</Text></View>{focus.secondary[0] ? <View style={storyStyles.focusLegendItem}><View style={[storyStyles.focusLegendDot, { backgroundColor: '#E347CF' }]} /><Text style={storyStyles.focusLegendText}>{storyboardMuscleLabel(focus.secondary[0])}</Text></View> : null}</View>{completed ? <View style={storyStyles.dayEvidence}><MetricCell label="RPE" value={String(session.recap?.session_rpe ?? session.recap?.average_rpe ?? '—')} detail="Session" /><MetricCell label="Sets" value={String(session.recap?.logged_set_count ?? session.log_count ?? '—')} detail="Completed" /><MetricCell label="Duration" value={duration && !duration.isEstimate ? `${duration.minutes}m` : 'Not recorded'} detail="Actual" /></View> : <View style={storyStyles.dayEvidence}><MetricCell label="Duration" value={duration ? `${duration.isEstimate ? '~' : ''}${duration.minutes}m` : '—'} detail={duration?.isEstimate ? 'Estimated' : 'Actual'} /><MetricCell label="Movements" value={String(session.preview?.movement_count || session.focus?.core_count || 0)} detail="Programmed" /></View>}<SLButton label={completed ? 'View Session' : 'Open Session'} onPress={() => onOpenSession(session.id, { blockId, week: weekIndex, day: day.key })} /></View>;
}

type ProgrammingManagerSheetProps = {
  visible: boolean;
  accessibilityLabel: string;
  title: string;
  eyebrow?: string;
  subtitle?: string;
  busy?: boolean;
  heightFraction?: number;
  scroll?: boolean;
  keyboardAware?: boolean;
  onClose: () => void;
  children: React.ReactNode;
};

function ProgrammingManagerSheet({
  visible,
  accessibilityLabel,
  title,
  eyebrow,
  subtitle,
  busy = false,
  heightFraction = 0.86,
  scroll = true,
  keyboardAware = false,
  onClose,
  children,
}: ProgrammingManagerSheetProps) {
  const sheetRef = useRef<StrengthLedgerBottomSheetHandle>(null);
  const requestClose = useCallback(() => {
    if (busy) return;
    void Haptics.selectionAsync().catch(() => undefined);
    sheetRef.current?.dismiss();
  }, [busy]);
  const body = scroll ? (
    <ScrollView
      bounces
      contentContainerStyle={styles.programmingSheetScrollContent}
      keyboardDismissMode="interactive"
      keyboardShouldPersistTaps="handled"
      showsVerticalScrollIndicator
      style={styles.programmingSheetScroll}
    >
      {children}
    </ScrollView>
  ) : children;

  return (
    <StrengthLedgerBottomSheet
      ref={sheetRef}
      accessibilityLabel={accessibilityLabel}
      heightFraction={heightFraction}
      motionPreset="deliberate"
      onDismiss={onClose}
      onRequestClose={requestClose}
      visible={visible}
    >
      <KeyboardAvoidingView
        behavior={keyboardAware && Platform.OS === 'ios' ? 'padding' : undefined}
        style={styles.programmingSheetKeyboard}
      >
        <View style={styles.programmingSheetHeader}>
          <View style={styles.programmingSheetHeading}>
            {eyebrow ? <Text style={styles.programmingSheetEyebrow}>{eyebrow}</Text> : null}
            <Text numberOfLines={2} style={styles.programmingSheetTitle}>{title}</Text>
            {subtitle ? <Text numberOfLines={3} style={styles.programmingSheetSubtitle}>{subtitle}</Text> : null}
          </View>
        </View>
        <View style={styles.programmingSheetBody}>{body}</View>
      </KeyboardAvoidingView>
    </StrengthLedgerBottomSheet>
  );
}

function StoryboardSheet({ visible, title, onClose, children }: { visible: boolean; title: string; onClose: () => void; children: React.ReactNode }) {
  return (
    <ProgrammingManagerSheet
      accessibilityLabel={title}
