function weekCopyPlanningCandidate(week: RoadmapWeek & { startDate: string }): ProgrammingWeekCopyCandidate {
  return {
    key: roadmapWeekIdentityKey(week),
    blockId: week.blockId,
    blockName: week.blockName,
    blockOrder: week.blockOrder,
    weekIndex: week.index,
    startDate: week.startDate,
    sessionCount: storyboardWeekSessionCount(week),
  };
}

function weekCopySessionPreview(week: RoadmapWeek) {
  return week.days
    .flatMap((day) => day.sessions)
    .map((session) => compactCopiedSessionTitle(sessionTitle(session)))
    .filter(Boolean)
    .slice(0, 5);
}

function WeekActionModal({
  state,
  weeks,
  busy,
  warning,
  confirmed,
  onClose,
  onSubmit,
}: {
  state: WeekActionState | null;
  weeks: RoadmapWeek[];
  busy: boolean;
  warning: string;
  confirmed: boolean;
  onClose: () => void;
  onSubmit: (action: WeekActionKey, week: RoadmapWeek, extra?: Record<string, any>) => void | Promise<void>;
}) {
  const action = state?.action || null;
  const week = state?.week || null;
  const isCopyAction = action === 'copy-from' || action === 'copy-to';
  const availableWeeks = useMemo(
    () => weeks.filter((candidate) => (
      candidate.startDate
      && roadmapWeekIdentityKey(candidate) !== (week ? roadmapWeekIdentityKey(week) : '')
      && (action !== 'shift' || candidate.blockId === week?.blockId)
    )),
    [action, week, weeks]
  );
  const rankedCopyWeeks = useMemo(() => {
    if (!week || !isCopyAction || !week.startDate) return [] as RoadmapWeek[];
    const planningRows = availableWeeks
      .filter((candidate): candidate is RoadmapWeek & { startDate: string } => Boolean(candidate.startDate))
      .map(weekCopyPlanningCandidate);
    const rankedKeys = rankProgrammingWeekCopyCandidates(
      action,
      weekCopyPlanningCandidate(week as RoadmapWeek & { startDate: string }),
      planningRows,
    ).map((candidate) => candidate.key);
    const byKey = new Map(availableWeeks.map((candidate) => [roadmapWeekIdentityKey(candidate), candidate]));
    return rankedKeys.map((key) => byKey.get(key)).filter((candidate): candidate is RoadmapWeek => Boolean(candidate));
  }, [action, availableWeeks, isCopyAction, week]);
  const availableWeekGroups = useMemo(() => {
    if (!week) return [] as Array<{ title: string; weeks: RoadmapWeek[] }>;
    const blockOrder = Array.from(new Set(weeks.map((candidate) => candidate.blockId)));
    const currentBlockIndex = blockOrder.indexOf(week.blockId);
    const previousBlockId = currentBlockIndex > 0 ? blockOrder[currentBlockIndex - 1] : null;
    const groups = [
      { title: 'Current Block', weeks: availableWeeks.filter((candidate) => candidate.blockId === week.blockId) },
      { title: 'Previous Block', weeks: availableWeeks.filter((candidate) => candidate.blockId === previousBlockId) },
      { title: 'Earlier / Later', weeks: availableWeeks.filter((candidate) => candidate.blockId !== week.blockId && candidate.blockId !== previousBlockId) },
    ];
    return groups.filter((group) => group.weeks.length);
  }, [availableWeeks, week, weeks]);
  const [selectedWeekKey, setSelectedWeekKey] = useState('');
  const [templateName, setTemplateName] = useState('');
  const [templates, setTemplates] = useState<WeekTemplate[]>([]);
  const [selectedTemplateId, setSelectedTemplateId] = useState('');
  const [templateError, setTemplateError] = useState('');
  const [objective, setObjective] = useState('');
  const [weekTag, setWeekTag] = useState('');
  const [expandedCopyBlocks, setExpandedCopyBlocks] = useState<Record<number, boolean>>({});
  const needsWeekChoice = action === 'copy-to' || action === 'copy-from' || action === 'shift';
  const needsTemplateChoice = action === 'apply-template';

  useEffect(() => {
    if (!state) return;
    const firstWeek = (state.action === 'copy-from' || state.action === 'copy-to')
      ? rankedCopyWeeks[0]
      : weeks.find((candidate) => (
      candidate.startDate
      && roadmapWeekIdentityKey(candidate) !== roadmapWeekIdentityKey(state.week)
      && (state.action !== 'shift' || candidate.blockId === state.week.blockId)
    ));
    setSelectedWeekKey(firstWeek ? roadmapWeekIdentityKey(firstWeek) : '');
    setTemplateName(`Week ${state.week.index} Template`);
    setSelectedTemplateId('');
    setTemplateError('');
    setObjective(state.week.objective?.text || '');
    setWeekTag(state.week.tag?.key || '');
    setExpandedCopyBlocks({});
  }, [rankedCopyWeeks, state, weeks]);

  useEffect(() => {
    if (action !== 'apply-template') return;
    let active = true;
    setTemplateError('');
    fetchJson<any>('/workouts/mobile/programming/week-templates', { method: 'GET' })
      .then((resp) => {
        const json = resp.json || {};
        if (!resp.ok || !json.ok) throw new Error(json.error || `HTTP ${resp.status}`);
        if (!active) return;
        const rows = json.templates || [];
        setTemplates(rows);
        setSelectedTemplateId(rows[0]?.id ? String(rows[0].id) : '');
      })
      .catch((err) => {
        if (!active) return;
        setTemplates([]);
        setTemplateError(err?.message || 'Week templates could not be loaded.');
      });
    return () => {
      active = false;
    };
  }, [action]);

  if (!state || !week || !action) return null;

  const selectedWeek = weeks.find((candidate) => roadmapWeekIdentityKey(candidate) === selectedWeekKey) || null;
  const selectedTemplate = templates.find((template) => String(template.id) === selectedTemplateId) || null;
  const canConfirm = !busy && (
    needsWeekChoice ? !!selectedWeek?.startDate
      : needsTemplateChoice ? !!selectedTemplateId
        : true
  );
  const submitLabel = action === 'clear' && confirmed
    ? 'Clear Week'
    : confirmed
      ? action === 'shift' ? 'Shift Anyway' : action === 'apply-template' ? 'Apply Anyway' : 'Copy Anyway'
      : action === 'clear'
        ? 'Review Clear'
        : action === 'edit-objective'
          ? 'Save Objective'
          : action === 'set-tag'
            ? 'Save Focus'
        : 'Confirm';
  const extra: Record<string, any> = {};
  if ((action === 'copy-to' || action === 'shift') && selectedWeek?.startDate) {
    extra.target_week_start = selectedWeek.startDate;
    extra.target_block_id = selectedWeek.blockId;
    extra.target_block_week_index = selectedWeek.index;
  }
  if (action === 'copy-from') {
    extra.source_week_start = selectedWeek?.startDate;
    extra.source_block_id = selectedWeek?.blockId;
    extra.source_block_week_index = selectedWeek?.index;
    extra.target_week_start = week.startDate;
    extra.target_block_id = week.blockId;
    extra.target_block_week_index = week.index;
  }
  if (action === 'save-template') extra.template_name = templateName;
  if (action === 'apply-template') {
    extra.template_id = selectedTemplateId;
    extra.target_week_start = week.startDate;
  }
  if (action === 'edit-objective') extra.objective = objective;
  if (action === 'set-tag') extra.week_tag = weekTag;

  const copyContextLabel = action === 'copy-from' ? 'COPY INTO' : action === 'copy-to' ? 'COPY FROM' : null;
  const copySourceWeek = action === 'copy-from' ? selectedWeek : action === 'copy-to' ? week : null;
  const copyDestinationWeek = action === 'copy-from' ? week : action === 'copy-to' ? selectedWeek : null;
  const copySessionCount = copySourceWeek ? storyboardWeekSessionCount(copySourceWeek) : 0;
  const copyDestinationCount = copyDestinationWeek ? storyboardWeekSessionCount(copyDestinationWeek) : 0;
  if (isCopyAction && copyDestinationCount > 0) extra.confirm_conflicts = true;

  if (isCopyAction) {
    const recommendedWeeks = rankedCopyWeeks.slice(0, 3);
    const primaryWeeks = action === 'copy-from'
      ? rankedCopyWeeks.filter((candidate) => candidate.blockId === week.blockId)
      : rankedCopyWeeks.filter((candidate) => storyboardWeekSessionCount(candidate) === 0);
    const secondaryWeeks = action === 'copy-from'
      ? rankedCopyWeeks.filter((candidate) => candidate.blockId !== week.blockId)
      : rankedCopyWeeks.filter((candidate) => storyboardWeekSessionCount(candidate) > 0);
    const secondaryBlocks = Array.from(secondaryWeeks.reduce((groups, candidate) => {
      const existing = groups.get(candidate.blockId) || { blockId: candidate.blockId, name: candidate.blockName, weeks: [] as RoadmapWeek[] };
      existing.weeks.push(candidate);
      groups.set(candidate.blockId, existing);
      return groups;
    }, new Map<number, { blockId: number; name: string; weeks: RoadmapWeek[] }>()).values());
    const renderCandidate = (candidate: RoadmapWeek, compact = false) => {
      const candidateKey = roadmapWeekIdentityKey(candidate);
      const selected = candidateKey === selectedWeekKey;
      const sessionCount = storyboardWeekSessionCount(candidate);
      const preview = weekCopySessionPreview(candidate);
      return (
        <SLMotionPressable
          key={`${compact ? 'recommended' : 'candidate'}:${candidateKey}`}
          accessibilityRole="radio"
          accessibilityState={{ selected }}
          onPress={() => {
            void Haptics.selectionAsync().catch(() => undefined);
            setSelectedWeekKey(candidateKey);
          }}
          pressScale={0.985}
          style={({ pressed }) => [
            compact ? styles.weekCopyRecommendedCard : styles.weekCopyCandidateRow,
            selected && styles.weekCopyCandidateSelected,
            pressed && styles.pressed,
          ]}
        >
          <View style={styles.weekCopyCandidateIcon}>
            <Ionicons name="calendar-outline" size={21} color={selected ? colors.violet : colors.muted} />
          </View>
          <View style={styles.weekCopyCandidateBody}>
            <View style={styles.weekCopyCandidateHeading}>
              <View style={styles.weekCopyCandidateHeadingCopy}>
                <Text numberOfLines={1} style={[styles.weekCopyCandidateTitle, selected && styles.weekChoiceTitleSelected]}>{candidate.blockName} · Week {candidate.index}</Text>
                <Text style={styles.weekChoiceMeta}>{candidate.rangeLabel}</Text>
              </View>
              {selected ? <Ionicons name="checkmark-circle" size={21} color={colors.violet} /> : <View style={styles.weekCandidateRadio} />}
            </View>
            {preview.length ? (
              <View style={styles.weekCopySplitRow}>
                {preview.map((title, index) => <Text key={`${title}:${index}`} numberOfLines={1} style={styles.weekCopySplitChip}>{title}</Text>)}
              </View>
            ) : null}
            <Text style={[styles.weekCandidateSessions, sessionCount ? styles.weekCandidatePopulated : styles.weekCandidateEmpty]}>
              {sessionCount ? `${sessionCount} Session${sessionCount === 1 ? '' : 's'}` : 'Empty week'}
            </Text>
          </View>
        </SLMotionPressable>
      );
    };

    return (
      <ProgrammingManagerSheet
        accessibilityLabel={action === 'copy-from' ? 'Copy From' : 'Copy To'}
        busy={busy}
        eyebrow="Week action"
        heightFraction={0.94}
        onClose={onClose}
        scroll={false}
        subtitle={action === 'copy-from' ? 'Select the populated week you want to copy' : 'Select the week you want to copy into'}
        title={action === 'copy-from' ? 'Copy From' : 'Copy To'}
        visible
      >
        <View style={styles.weekCopyShell}>
          <View style={styles.weekCopyContext}>
            <View style={styles.weekCopyContextCopy}>
              <Text style={styles.weekCopyContextLabel}>{copyContextLabel}</Text>
              <Text style={styles.weekCopyContextTitle}>{week.blockName} · Week {week.index}</Text>
              <Text style={styles.weekCopyContextMeta}>{week.rangeLabel} · {storyboardWeekSessionCount(week) ? `${storyboardWeekSessionCount(week)} Sessions` : 'No sessions planned'}</Text>
            </View>
            <View style={styles.weekCopyContextIcon}><Ionicons name={action === 'copy-from' ? 'calendar-outline' : 'clipboard-outline'} size={25} color={colors.violet} /></View>
          </View>

          <ScrollView
            bounces
            contentContainerStyle={styles.weekCopyPickerContent}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator
            style={styles.weekCopyPicker}
          >
            {action === 'copy-from' && recommendedWeeks.length ? (
              <View style={styles.weekCopySection}>
                <Text style={styles.weekCopySectionTitle}>Recommended</Text>
                <Text style={styles.weekCopySectionHint}>Closest populated weeks first</Text>
                <ScrollView horizontal contentContainerStyle={styles.weekCopyRecommendedRail} showsHorizontalScrollIndicator={false}>
                  {recommendedWeeks.map((candidate) => renderCandidate(candidate, true))}
                </ScrollView>
              </View>
            ) : null}

            <View style={styles.weekCopySection}>
              <Text style={styles.weekCopySectionTitle}>{action === 'copy-from' ? `This block · ${week.blockName}` : 'Upcoming empty weeks'}</Text>
              <Text style={styles.weekCopySectionHint}>{action === 'copy-from' ? 'Populated weeks in this block' : 'Empty destinations are prioritized'}</Text>
              <View style={styles.weekCopyCandidateList}>
                {primaryWeeks.length ? primaryWeeks.map((candidate) => renderCandidate(candidate)) : <Text style={styles.weekActionEmpty}>{action === 'copy-from' ? 'No populated source weeks are available in this block.' : 'No empty destination weeks are available.'}</Text>}
              </View>
            </View>

            {secondaryBlocks.map((group) => {
              const expanded = !!expandedCopyBlocks[group.blockId];
              return (
                <View key={group.blockId} style={styles.weekCopyCollapsedBlock}>
                  <SLMotionPressable
                    accessibilityRole="button"
                    accessibilityState={{ expanded }}
                    onPress={() => {
                      void Haptics.selectionAsync().catch(() => undefined);
                      setExpandedCopyBlocks((current) => ({ ...current, [group.blockId]: !current[group.blockId] }));
                    }}
                    pressScale={0.99}
                    style={({ pressed }) => [styles.weekCopyCollapsedHeader, pressed && styles.pressed]}
                  >
                    <View>
                      <Text style={styles.weekCopySectionTitle}>{group.name}</Text>
                      <Text style={styles.weekCopySectionHint}>{group.weeks.length} {action === 'copy-from' ? 'populated' : 'already populated'} week{group.weeks.length === 1 ? '' : 's'}</Text>
                    </View>
                    <Ionicons name={expanded ? 'chevron-up' : 'chevron-down'} size={18} color={colors.muted} />
                  </SLMotionPressable>
                  {expanded ? <View style={styles.weekCopyCandidateList}>{group.weeks.map((candidate) => renderCandidate(candidate))}</View> : null}
                </View>
              );
            })}

            {!rankedCopyWeeks.length ? <Text style={styles.weekActionEmpty}>{action === 'copy-from' ? 'No populated source weeks are available.' : 'No destination weeks are available.'}</Text> : null}
          </ScrollView>

          <View style={styles.weekCopySummary}>
            {copySourceWeek && copyDestinationWeek ? (
              <>
                <View style={styles.weekCopySummaryRoute}>
                  <Text numberOfLines={1} style={styles.weekCopySummaryWeek}>{copySourceWeek.blockName} · W{copySourceWeek.index}</Text>
                  <Ionicons name="arrow-forward" size={16} color={colors.muted} />
                  <Text numberOfLines={1} style={styles.weekCopySummaryWeek}>{copyDestinationWeek.blockName} · W{copyDestinationWeek.index}</Text>
                </View>
                <Text style={styles.weekCopySummaryMeta}>{copyDestinationCount ? `${copyDestinationCount} existing Session${copyDestinationCount === 1 ? '' : 's'} · New copies will be appended as drafts.` : 'Empty destination · Sessions will be created as drafts.'}</Text>
              </>
            ) : <Text style={styles.weekCopySummaryMeta}>Select a week to preview the copy.</Text>}
            {warning ? <Text style={styles.weekActionWarning}>{warning}</Text> : null}
            <SLMotionPressable
              accessibilityRole="button"
              disabled={!canConfirm || copySessionCount < 1}
              onPress={() => onSubmit(action, week, extra)}
              pressScale={0.985}
              style={({ pressed }) => [styles.weekCopyPrimary, (!canConfirm || copySessionCount < 1) && styles.weekActionDisabled, pressed && canConfirm && styles.pressed]}
            >
              <LinearGradient colors={['#5E23C7', '#8A2B8D']} end={{ x: 1, y: 0 }} style={StyleSheet.absoluteFillObject} />
              {busy ? <ActivityIndicator size="small" color={colors.textStrong} /> : <Ionicons name="copy-outline" size={18} color={colors.textStrong} />}
              <Text style={styles.weekActionPrimaryText}>{busy ? 'Copying…' : `Copy ${copySessionCount} Session${copySessionCount === 1 ? '' : 's'}`}</Text>
            </SLMotionPressable>
          </View>
        </View>
      </ProgrammingManagerSheet>
    );
  }

  return (
    <ProgrammingManagerSheet
      accessibilityLabel={weekActionLabel(action)}
      busy={busy}
      eyebrow={action === 'edit-objective' ? 'Week objective' : action === 'set-tag' ? 'Week focus' : 'Week action'}
      heightFraction={needsWeekChoice ? 0.91 : 0.78}
      keyboardAware={action === 'edit-objective' || action === 'save-template'}
      onClose={onClose}
      subtitle={`Week ${week.index} · ${week.rangeLabel}`}
      title={weekActionLabel(action)}
      visible
    >
      <View style={styles.weekActionModal}>
          {copyContextLabel ? (
            <View style={styles.weekCopyContext}>
              <Text style={styles.weekCopyContextLabel}>{copyContextLabel}</Text>
              <Text style={styles.weekCopyContextTitle}>{week.blockName} · Week {week.index}</Text>
              <Text style={styles.weekCopyContextMeta}>{week.rangeLabel} · {week.summary}</Text>
            </View>
          ) : null}

          {!needsWeekChoice ? <Text style={styles.weekActionCopy}>{weekActionCopy(action)}</Text> : null}

          {action === 'edit-objective' ? (
            <View style={styles.weekActionField}>
              <Text style={styles.weekActionFieldLabel}>Week objective</Text>
              <TextInput
                value={objective}
                onChangeText={setObjective}
                multiline
                maxLength={800}
                textAlignVertical="top"
                placeholder="What should the athlete accomplish this week?"
                placeholderTextColor={colors.subtle}
                style={[styles.weekActionInput, styles.weekActionTextArea]}
              />
              <Text style={styles.weekActionFieldHint}>{objective.length}/800</Text>
              {objective.trim() ? (
                <Pressable
                  accessibilityRole="button"
                  onPress={() => {
                    void Haptics.selectionAsync().catch(() => undefined);
                    setObjective('');
                  }}
                  style={({ pressed }) => [styles.weekActionClear, pressed && styles.pressed]}
                >
                  <Text style={styles.weekActionClearText}>Clear Objective</Text>
                </Pressable>
              ) : null}
            </View>
          ) : null}

          {action === 'set-tag' ? (
            <View style={styles.weekChoiceList}>
              <Text style={styles.weekActionFieldLabel}>Week focus</Text>
              {trainingWeekTags.map((tag) => {
                const selected = tag.key === weekTag;
                return (
                  <Pressable
                    key={tag.key || 'standard'}
                    accessibilityRole="radio"
                    accessibilityState={{ selected }}
                    onPress={() => setWeekTag(tag.key)}
                    style={[styles.weekChoiceRow, selected && styles.weekChoiceRowSelected]}
                  >
                    <View>
                      <Text style={[styles.weekChoiceTitle, selected && styles.weekChoiceTitleSelected]}>{tag.label}</Text>
                      {!tag.key ? <Text style={styles.weekChoiceMeta}>No special week tag</Text> : null}
                    </View>
                    {selected ? <Ionicons name="checkmark-circle" size={20} color={colors.violet} /> : null}
                  </Pressable>
                );
              })}
            </View>
          ) : null}

          {needsWeekChoice ? (
            <View style={styles.weekChoiceList}>
              <Text style={styles.weekActionFieldLabel}>CHOOSE DESTINATION WEEK</Text>
              {availableWeekGroups.length ? availableWeekGroups.map((group) => (
                <View key={group.title} style={styles.weekCandidateGroup}>
                  <Text style={styles.weekCandidateGroupTitle}>{group.title}</Text>
                  <View style={styles.weekCandidateGrid}>
                    {group.weeks.map((candidate) => {
                      const candidateKey = roadmapWeekIdentityKey(candidate);
                      const selected = candidateKey === selectedWeekKey;
                      const sessionCount = storyboardWeekSessionCount(candidate);
                      return (
                        <Pressable
                          key={candidateKey}
                          accessibilityRole="radio"
                          accessibilityState={{ selected }}
                          onPress={() => {
                            void Haptics.selectionAsync().catch(() => undefined);
                            setSelectedWeekKey(candidateKey);
                          }}
                          style={({ pressed }) => [
                            styles.weekCandidateCard,
                            selected && styles.weekChoiceRowSelected,
                            pressed && styles.pressed,
                          ]}
                        >
                          <View style={styles.weekCandidateCardCopy}>
                            <Text numberOfLines={1} style={[styles.weekChoiceTitle, selected && styles.weekChoiceTitleSelected]}>{candidate.blockName}</Text>
                            <Text style={[styles.weekCandidateWeek, selected && styles.weekChoiceTitleSelected]}>Week {candidate.index}</Text>
                            <Text style={styles.weekChoiceMeta}>{candidate.rangeLabel}</Text>
                            <Text style={[styles.weekCandidateSessions, sessionCount ? styles.weekCandidatePopulated : styles.weekCandidateEmpty]}>
                              {sessionCount} {sessionCount === 1 ? 'Session' : 'Sessions'}
                            </Text>
                          </View>
                          {selected ? <Ionicons name="checkmark-circle" size={21} color={colors.violet} /> : <View style={styles.weekCandidateRadio} />}
                        </Pressable>
                      );
                    })}
                  </View>
                </View>
              )) : (
                <Text style={styles.weekActionEmpty}>No other weeks available.</Text>
              )}
            </View>
          ) : null}

          {action === 'save-template' ? (
            <View style={styles.weekActionField}>
              <Text style={styles.weekActionFieldLabel}>Template name</Text>
              <TextInput
                value={templateName}
                onChangeText={setTemplateName}
                placeholder="Week template name"
                placeholderTextColor={colors.subtle}
                style={styles.weekActionInput}
              />
            </View>
          ) : null}

          {needsTemplateChoice ? (
            <View style={styles.weekChoiceList}>
              <Text style={styles.weekActionFieldLabel}>Week template</Text>
              {templateError ? <Text style={styles.weekActionWarning}>{templateError}</Text> : null}
              {templates.length ? templates.map((template) => {
                const selected = String(template.id) === selectedTemplateId;
                return (
                  <Pressable
                    key={template.id}
                    onPress={() => setSelectedTemplateId(String(template.id))}
                    style={[styles.weekChoiceRow, selected && styles.weekChoiceRowSelected]}
                  >
                    <View>
                      <Text style={[styles.weekChoiceTitle, selected && styles.weekChoiceTitleSelected]}>{template.name || 'Week Template'}</Text>
                      <Text style={styles.weekChoiceMeta}>{Number(template.session_count || 0)} sessions</Text>
                    </View>
                    {selected ? <Ionicons name="checkmark-circle" size={20} color={colors.violet} /> : null}
                  </Pressable>
                );
              }) : !templateError ? (
                <Text style={styles.weekActionEmpty}>No saved week templates yet.</Text>
              ) : null}
            </View>
          ) : null}

          <View style={styles.weekActionPreview}>
            <Text style={styles.weekActionPreviewText}>
              {weekActionPreview(action, week, selectedWeek, selectedTemplate, objective, weekTag)}
            </Text>
          </View>

          {warning ? <Text style={styles.weekActionWarning}>{warning}</Text> : null}

          <View style={styles.weekActionFooter}>
            <Pressable
              disabled={busy}
              onPress={onClose}
              style={({ pressed }) => [styles.weekActionSecondary, pressed && styles.pressed]}
            >
              <Text style={styles.weekActionSecondaryText}>Cancel</Text>
            </Pressable>
            <Pressable
              disabled={!canConfirm}
              onPress={() => onSubmit(action, week, extra)}
              style={({ pressed }) => [
                styles.weekActionPrimary,
                !canConfirm && styles.weekActionDisabled,
                pressed && canConfirm && styles.pressed,
              ]}
            >
              <Text style={styles.weekActionPrimaryText}>{busy ? 'Working...' : submitLabel}</Text>
            </Pressable>
          </View>
      </View>
    </ProgrammingManagerSheet>
  );
}

function BlockActionModal({
  state,
  busy,
  warning,
  confirmed,
  onClose,
  onSubmit,
}: {
  state: BlockActionState | null;
  busy: boolean;
  warning: string;
  confirmed: boolean;
  onClose: () => void;
  onSubmit: (action: BlockActionKey, block: ProgramBlockPayload, extra?: Record<string, any>) => void | Promise<void>;
}) {
  const action = state?.action || null;
  const block = state?.block || null;
  const [templateName, setTemplateName] = useState('');
  const [templates, setTemplates] = useState<BlockTemplate[]>([]);
  const [selectedTemplateId, setSelectedTemplateId] = useState('');
  const [templateError, setTemplateError] = useState('');
  const needsTemplateChoice = action === 'apply-template';

  useEffect(() => {
    if (!state) return;
    setTemplateName(`${state.block.name || 'Block'} Template`);
    setSelectedTemplateId('');
    setTemplateError('');
  }, [state]);

  useEffect(() => {
    if (action !== 'apply-template') return;
    let active = true;
    setTemplateError('');
    fetchJson<any>('/workouts/mobile/programming/block-templates', { method: 'GET' })
      .then((resp) => {
        const json = resp.json || {};
        if (!resp.ok || !json.ok) throw new Error(json.error || `HTTP ${resp.status}`);
        if (!active) return;
        const rows = json.templates || [];
        setTemplates(rows);
        setSelectedTemplateId(rows[0]?.id ? String(rows[0].id) : '');
      })
      .catch((err) => {
        if (!active) return;
        setTemplates([]);
        setTemplateError(err?.message || 'Block templates could not be loaded.');
      });
    return () => {
      active = false;
    };
  }, [action]);

  if (!state || !block || !action) return null;

  const selectedTemplate = templates.find((template) => String(template.id) === selectedTemplateId) || null;
  const canConfirm = !busy && (needsTemplateChoice ? !!selectedTemplateId : true);
  const submitLabel = action === 'clear' && confirmed
    ? 'Clear Block Sessions'
    : confirmed
      ? action === 'apply-template' ? 'Apply Anyway' : 'Confirm'
      : action === 'clear'
        ? 'Review Clear'
        : 'Confirm';
  const extra: Record<string, any> = {};
  if (action === 'save-template') extra.template_name = templateName;
  if (action === 'apply-template') extra.template_id = selectedTemplateId;

  return (
    <ProgrammingManagerSheet
      accessibilityLabel={blockActionLabel(action)}
      busy={busy}
      eyebrow="Block action"
      heightFraction={needsTemplateChoice ? 0.82 : 0.66}
      keyboardAware={action === 'save-template'}
      onClose={onClose}
      subtitle={block.date_range_label || undefined}
      title={blockActionLabel(action)}
      visible
    >
      <View style={styles.weekActionModal}>

          <Text style={styles.weekActionCopy}>{blockActionCopy(action)}</Text>

          {action === 'save-template' ? (
            <View style={styles.weekActionField}>
              <Text style={styles.weekActionFieldLabel}>Template name</Text>
              <TextInput
                value={templateName}
                onChangeText={setTemplateName}
                placeholder="Block template name"
                placeholderTextColor={colors.subtle}
                style={styles.weekActionInput}
              />
            </View>
          ) : null}

          {needsTemplateChoice ? (
            <View style={styles.weekChoiceList}>
              <Text style={styles.weekActionFieldLabel}>Block template</Text>
              {templateError ? <Text style={styles.weekActionWarning}>{templateError}</Text> : null}
              {templates.length ? templates.map((template) => {
                const selected = String(template.id) === selectedTemplateId;
                return (
                  <Pressable
                    key={template.id}
                    onPress={() => setSelectedTemplateId(String(template.id))}
                    style={[styles.weekChoiceRow, selected && styles.weekChoiceRowSelected]}
                  >
                    <View>
                      <Text style={[styles.weekChoiceTitle, selected && styles.weekChoiceTitleSelected]}>{template.name || 'Block Template'}</Text>
                      <Text style={styles.weekChoiceMeta}>
                        {Number(template.week_count || template.default_duration_weeks || 0)} weeks · {Number(template.session_count || 0)} sessions
                      </Text>
                    </View>
                    {selected ? <Ionicons name="checkmark-circle" size={20} color={colors.violet} /> : null}
                  </Pressable>
                );
              }) : !templateError ? (
                <Text style={styles.weekActionEmpty}>No saved block templates yet.</Text>
              ) : null}
            </View>
          ) : null}

          <View style={styles.weekActionPreview}>
            <Text style={styles.weekActionPreviewText}>{blockActionPreview(action, block, selectedTemplate)}</Text>
          </View>

          {warning ? <Text style={styles.weekActionWarning}>{warning}</Text> : null}

          <View style={styles.weekActionFooter}>
            <Pressable
              disabled={busy}
              onPress={onClose}
              style={({ pressed }) => [styles.weekActionSecondary, pressed && styles.pressed]}
            >
              <Text style={styles.weekActionSecondaryText}>Cancel</Text>
            </Pressable>
            <Pressable
              disabled={!canConfirm}
              onPress={() => onSubmit(action, block, extra)}
              style={({ pressed }) => [
                styles.weekActionPrimary,
                !canConfirm && styles.weekActionDisabled,
                pressed && canConfirm && styles.pressed,
              ]}
            >
              <Text style={styles.weekActionPrimaryText}>{busy ? 'Working...' : submitLabel}</Text>
            </Pressable>
          </View>
      </View>
    </ProgrammingManagerSheet>
  );
}

function weekActionLabel(action: WeekActionKey) {
  return weekActionRows.find((row) => row.key === action)?.label || 'Week Action';
}

function roadmapWeekIdentityKey(week: RoadmapWeek) {
  if (!week.startDate) return `${week.blockId}:${week.index}:undated`;
  return canonicalProgrammingWeekKey({
    blockId: week.blockId,
    blockWeekIndex: week.index,
    weekStart: week.startDate,
  });
}

function weekActionIdentityLabel(week: RoadmapWeek) {
  return `${week.blockName} · Week ${week.index} · ${week.rangeLabel}`;
}

function weekActionCopy(action: WeekActionKey) {
  return {
    'edit-objective': 'Set the concise coach-authored objective the athlete will see for this week.',
    'set-tag': 'Set the training focus the athlete will see for this week in Training Hub.',
    'copy-to': 'Send this week’s training structure to another week in the same block.',
    'copy-from': 'Pull a week’s training structure into the selected week.',
    'apply-template': 'Apply a saved week structure to this week.',
    'save-template': 'Save this week’s structure so it can be reused later.',
    'assign-drafts': 'Assign all draft sessions in this week.',
    'revert-assigned': 'Revert all assigned sessions in this week back to draft.',
    shift: 'Move this week’s sessions to another week without leaving copies behind.',
    clear: 'Clear safe-to-remove sessions from this week.',
  }[action];
}

function weekActionPreview(
  action: WeekActionKey,
  source: RoadmapWeek,
  target: RoadmapWeek | null,
  template: WeekTemplate | null,
  objective = '',
  weekTag = ''
) {
  if (action === 'edit-objective') {
    return objective.trim()
      ? `Save this coach objective for Week ${source.index}.`
      : `Clear the coach objective from Week ${source.index}.`;
  }
  if (action === 'set-tag') {
    const tag = trainingWeekTags.find((candidate) => candidate.key === weekTag);
    return weekTag
      ? `Set Week ${source.index} focus to ${tag?.label || weekTag}.`
      : `Clear the special focus from Week ${source.index}.`;
  }
  if (action === 'copy-to') return `Copy ${weekActionIdentityLabel(source)} into ${target ? weekActionIdentityLabel(target) : 'the target week'}. Copied sessions will be drafts.`;
  if (action === 'copy-from') return `Copy ${target ? weekActionIdentityLabel(target) : 'the source week'} into ${weekActionIdentityLabel(source)}. Copied sessions will be drafts.`;
  if (action === 'apply-template') return `Apply ${template?.name || 'selected template'} to Week ${source.index}. Applied sessions become drafts.`;
  if (action === 'save-template') return `Save Week ${source.index} as a reusable week template.`;
  if (action === 'assign-drafts') return `Assign every draft session in Week ${source.index}. Completed, logged, and locked sessions are preserved.`;
  if (action === 'revert-assigned') return `Revert every assigned session in Week ${source.index} to draft. Completed, logged, and locked sessions are preserved.`;
  if (action === 'shift') return `Move ${weekActionIdentityLabel(source)} into ${target ? weekActionIdentityLabel(target) : 'the target week'}. Source week becomes empty.`;
  return `Remove safe draft/assigned sessions from Week ${source.index}. Logged or locked sessions are preserved.`;
}

function blockActionLabel(action: BlockActionKey) {
  return blockActionRows.find((row) => row.key === action)?.label || 'Block Action';
}

function blockActionCopy(action: BlockActionKey) {
  return {
    edit: 'Edit this block through the program editor.',
    'apply-template': 'Apply a saved block structure into the selected training block.',
    'save-template': 'Save this block’s week/session structure for reuse.',
    'assign-drafts': 'Assign all draft sessions in this block.',
    'revert-assigned': 'Revert all assigned sessions in this block back to draft.',
    clear: 'Clear all sessions that are safe to remove from this block.',
  }[action];
}

function blockActionPreview(action: BlockActionKey, block: ProgramBlockPayload, template: BlockTemplate | null) {
  const blockName = block.name || 'selected block';
  if (action === 'apply-template') return `Apply ${template?.name || 'selected block template'} into ${blockName}. Applied sessions become drafts.`;
  if (action === 'save-template') return `Save ${blockName} as a reusable block template.`;
  if (action === 'assign-drafts') return `Assign every draft session in ${blockName}. Completed, logged, and locked sessions are preserved.`;
  if (action === 'revert-assigned') return `Revert every assigned session in ${blockName} to draft. Completed, logged, and locked sessions are preserved.`;
  if (action === 'clear') return `Remove safe draft/assigned sessions from ${blockName}. Logged or locked sessions are preserved.`;
  return `Open ${blockName} in the program editor.`;
}

