      for (const item of group.items || []) {
        const logs = item.set_logs || [];
        const total = positiveInt(item.sets);
        const logged = loggedSetIndexCount(logs);
        rows.push({
          key: `acc:${item.id}`,
          detailKey: `acc:${item.id}`,
          kind: 'accessory',
          id: item.id,
          complete: total > 0 && logged >= total,
          logged,
          total,
        });
