    if (saveFeedbackTimerRef.current) clearTimeout(saveFeedbackTimerRef.current);
    saveFeedbackTimerRef.current = setTimeout(() => {
      feedbackDispatch({ type: 'SAVE_CONFIRMATION_FINISHED' });
