                          }}
                        />
                      </View>
                      <View style={styles.postSessionNativePickerRow}>
                        <Text style={styles.postSessionNativePickerLabel}>Time</Text>
                        <DateTimePicker
                          value={postSessionTimePickerDraft || new Date()}
                          mode="time"
                          display="spinner"
                          themeVariant="dark"
                          timeZoneName={postSessionTimeZone}
                          minuteInterval={1}
                          style={styles.postSessionNativeTimePicker}
                          onChange={(_event, selected) => {
                            if (selected) updatePostSessionTimePickerDraft('time', selected);
                          }}
                        />
                      </View>
                    </>
                  ) : (
                    <DateTimePicker
                      value={postSessionTimePickerDraft || new Date()}
                      mode={postSessionTimePickerMode}
                      display="default"
                      timeZoneName={postSessionTimeZone}
                      onChange={(event, selected) => {
                        if (event.type === 'dismissed' || !selected) {
                          closePostSessionTimePicker();
                          return;
                        }
                        const next = updatePostSessionTimePickerDraft(postSessionTimePickerMode, selected);
                        if (postSessionTimePickerMode === 'date') {
                          setPostSessionTimePickerMode('time');
                        } else if (next) {
                          commitPostSessionTimePicker(next);
                        }
                      }}
                    />
                  )
                )}

                <TouchableOpacity
                  accessibilityRole="button"
                  style={[styles.actionButton, styles.actionPrimary, styles.postSessionTimePickerDone]}
                  onPress={() => commitPostSessionTimePicker()}
                >
                  <Text style={[styles.actionButtonText, styles.actionPrimaryText]}>Done</Text>
                </TouchableOpacity>
                  </View>
                </View>
              ) : null}
            </View>
          </TouchableWithoutFeedback>
        </KeyboardAvoidingView>
      </Modal>

      {/* Shared rest timer picker (popup modal) */}
      {!warmupSheetItem ? <RestTimerPickerModal
          visible={timerPickerVisible}
          timerWheelRef={timerWheelRef}
          timerPickerValue={timerPickerValue}
          setTimerPickerValue={setTimerPickerValue}
          startRestTimer={confirmRestTimerSelection}
          onSkip={stopRestTimer}
          saveConfirmationVisible={feedbackState.recognition.saveConfirmationVisible}
          onMounted={handleTimerPickerMounted}
          onClose={resolveActiveTimerHandoff}
          styles={styles}
        /> : null}

      <SmartWarmupSheet
        item={warmupSheetItem}
        workoutId={Number(workout.id)}
        preferredUnit={unit}
        visible={Boolean(warmupSheetItem)}
        onClose={() => setWarmupItemId(null)}
        onRefresh={onRefresh}
        onOpenRestTimerPicker={openTimerPicker}
        restTimerActive={restActive}
        restTimer={activeRestTimer}
        onStopRestTimer={stopRestTimer}
        restTimerPicker={<RestTimerPickerModal
          embedded
          visible={timerPickerVisible}
          timerWheelRef={timerWheelRef}
          timerPickerValue={timerPickerValue}
          setTimerPickerValue={setTimerPickerValue}
          startRestTimer={confirmRestTimerSelection}
          onSkip={stopRestTimer}
          saveConfirmationVisible={false}
          onMounted={handleTimerPickerMounted}
          onClose={resolveActiveTimerHandoff}
          styles={styles}
        />}
      />

      {/* Readiness survey modal (mobile only, shown on Begin Session). */}
      <ReadinessModal
        visible={readinessVisible}
        unit={unit}
        priorBodyweightKg={data?.athlete?.bodyweight_kg}
        values={readinessForm}
        error={readinessError}
        submitting={readinessSubmitting}
        reduceMotion={reduceMotion}
        onChange={setReadinessForm}
        checking={readinessChecking}
        canSubmit={readinessCanSubmit}
        existing={existingReadiness}
        readOnly={isCoachAthletePreview}
        onSubmit={() => { void chooseReadinessAndBegin('submit'); }}
        onSkip={() => { void chooseReadinessAndBegin('skip'); }}
        onCancel={cancelReadiness}
      />

      <ApprovedSubstitutionPicker
        visible={swapPickerVisible && substitutionAuthority === 'coach_restricted'}
        choices={approvedSubstitutionIdentities(swapAccItem?.approved_sub_identities) as GovernedAccessoryIdentity[]}
        currentName={swapAccItem ? accessoryExecutionName(swapAccItem) : ''}
        prescription={swapPreviousPrescription}
        onCancel={() => { setSwapPickerVisible(false); setSwapAccItem(null); }}
        onSelect={(identity) => {
          setSwapAccIdentity(identity as GeneralMovementIdentity);
          setSwapError(null);
          setSwapPickerVisible(false);
          setSwapAccVisible(true);
        }}
      />
      {/* Accessory substitution modal */}
      <GovernedAccessorySubstitutionPickerModal
        context="in-session-substitution"
        visible={swapPickerVisible && substitutionAuthority === 'self_governed'}
        athleteId={data?.athlete?.id || null}
        athleteAnatomy={{
          anatomy_display_preference: data?.athlete?.anatomy_display_preference,
          sex: data?.athlete?.sex,
        }}
        title="Swap Accessory"
        currentIdentity={(swapAccItem ? resolveLoggerMovementIdentity(swapAccItem).effective : null) as GovernedAccessoryIdentity | null}
        currentPrescription={swapPreviousPrescription}
        canCreateCustom={
          substitutionAuthority === 'self_governed'
          && data?.permissions?.can_create_custom_movement === true
        }
        onCancel={() => {
          setSwapPickerVisible(false);
          setSwapAccItem(null);
        }}
        onSelect={(identity) => {
          setSwapAccIdentity(identity as GeneralMovementIdentity);
          setSwapPickerVisible(false);
          setSwapAccVisible(true);
        }}
      />

      <SubstitutionConfirmationSheet
        error={swapError}
        editablePrescription={substitutionAuthority === 'self_governed'}
        equipmentUnresolved={swapAccIdentity?.requires_equipment_configuration === true}
        onBack={() => {
          setSwapAccVisible(false);
          setSwapPickerVisible(true);
        }}
        onCancel={() => setSwapAccVisible(false)}
        onConfirm={saveSwapAcc}
        onRepTargetChange={setSwapRepTarget}
        onResetPrescription={resetSwapPrescription}
        onRirChange={(rir) => setSwapAccForm((value) => ({ ...value, rir }))}
        onSetsChange={(sets) => setSwapAccForm((value) => ({ ...value, sets }))}
        performingIdentity={swapAccIdentity}
        performingName={swapAccIdentity?.display_name || 'Choose movement'}
        programmedIdentity={(swapAccItem ? resolveLoggerMovementIdentity(swapAccItem).effective : null) as GeneralMovementIdentity | null}
        programmedName={swapAccItem ? accessoryExecutionName(swapAccItem) : 'Accessory'}
        previousPrescription={swapPreviousPrescription}
        prescriptionModified={swapReplacementPrescription !== swapPreviousPrescription}
        repTarget={swapRepTarget}
        replacementPrescription={swapReplacementPrescription}
        rir={swapAccForm.rir}
        saving={savingItemId === swapAccItem?.id}
        sets={swapAccForm.sets}
        visible={swapAccVisible}
      />

    </View>
  );
}

