    const message = String(error?.message || error || '');
    const staleConflict = /stale|already been logged|conflict|refresh/i.test(message);
    feedbackDispatch({ type: 'SUBMIT_FAILED', staleConflict });
    void triggerSubmissionFailureHaptic();
    feedbackAnalytics('set_save_feedback_failure', { stale_conflict: staleConflict });
    return staleConflict;
  }, []);

  const submitCanonicalSet = useCallback(async ({
    itemId,
    attemptKey,
    clientSubmissionId,
    request,
    fallbackError,
  }: {
    itemId: number;
    attemptKey: string;
    clientSubmissionId: string;
    request: () => Promise<any>;
    fallbackError: string;
  }) => {
    const ownerAtDispatch = executionScope;
    const outcome = await canonicalSetSubmissionControllerRef.current.run({
      onStarted: () => {
        beginFeedbackSubmission(itemId);
        setSavingItemId(itemId);
        setError(null);
      },
      request: () => recoverCanonicalSetSave({
        clientSubmissionId,
        request,
        assertOwner: () => {
          if (!screenMountedRef.current || executionScopeRef.current !== ownerAtDispatch) throw new Error('Session ownership changed.');
        },
        onRecovery: (attempt, failure) => feedbackAnalytics('set_save_transport_recovery', { attempt, failure }),
      }),
      onAccepted: (json) => {
        if (executionScopeRef.current !== ownerAtDispatch) return null;
        if (!consumeSetResultOnce(attemptKey, clientSubmissionId, json)) {
          feedbackAnalytics('recognition_replay_suppressed', {
            set_log_id: Number(json?.set?.id || 0),
            duplicate_local_result: true,
          });
          const replay = { ...json, created: false, replayed: true };
          handleCanonicalSetFeedback(replay, itemId);
          return replay;
        }
        handleCanonicalSetFeedback(json, itemId);
        return json;
      },
      onFailure: (error: any) => {
        if (executionScopeRef.current !== ownerAtDispatch) return;
        handleCanonicalSetFailure(error);
        setError(criticalMutationFailureMessage(error, fallbackError));
      },
      onSettled: () => { if (executionScopeRef.current === ownerAtDispatch) setSavingItemId(null); },
    });

    if (outcome.status === 'failed') {
      console.log('canonical set submission error', outcome.error);
      return null;
    }
    if (outcome.status !== 'accepted' || executionScopeRef.current !== ownerAtDispatch) return null;
    return outcome.value;
