  coach?: {
    id?: number;
    name?: string | null;
    email?: string | null;
  } | null;
  phase?: {
    label?: string | null;
    active_program?: {
      id?: number | null;
      name?: string | null;
      start_date?: string | null;
      end_date?: string | null;
    } | null;
    block?: {
      id?: number;
      name?: string | null;
      start_date?: string | null;
