  latest_announcement?: CoachConnectionItem | null;
  latest_message?: CoachConnectionItem | null;
  recent_glance?: {
    title?: string | null;
    date?: string | null;
    status?: string | null;
    workout_id?: number | null;
  } | null;
  week_preview?: TodaySession[] | null;
  yesterday?: DayTrainingState | null;
  next_glance?: {
