    kind?: string | null;
    label?: string | null;
    value?: number | null;
    unit?: string | null;
    delta?: number | null;
    body?: string | null;
  } | null;
  primary_action?: TodayAction | null;
  home_v3?: AthleteHomeV3Projection | null;
