          ) : null}
        </View>

        {items.map((item) => {
          const icon = item.selected && item.icon.endsWith('-outline')
            ? (item.icon.replace('-outline', '') as keyof typeof Ionicons.glyphMap)
            : item.icon;
          const color = item.selected
            ? SL_TAB_ROW_CONTROL.selectedColor
