el="Return to the record" onPress={() => setSheet(null)} icon="arrow-back" /></> : sheet === 'search' ? <><View style={s.searchField}><Icon name="search-outline" /><TextInput autoFocus testID="study-global-search" accessibilityLabel="Search all movements" value={searchQuery} onChangeText={setSearchQuery} placeholder="Squat, pull-up, equipment…" placeholderTextColor={C.muted} style={s.input} /></View><Text style={s.caption}>{searchQuery ? `${matches.length} matching movement records` : 'Start with a lift, or search your movements.'}</Text>{matches.map(m => <MovementRow key={m.id} m={m} unit={unit} onPress={() => openMovement(m)} />)}{!matches.length ? <Empty icon="search-outline" title="No matching record." body="Try a movement name or equipment manufacturer." /> : null}</> : sheet === 'tiers' ? <TierCollection unit={unit} firstWeek={firstWeek} /> : sheet === 'volume' ? <VolumeCollection unit={unit} firstWeek={firstWeek} onHistory={() => { setSheet(null); selectTab('history', true); }} /> : sheet === 'guide' ? <><Text style={s.bodyCopy}>A research-backed proposal for a clearer Ledger. All numbers here are fictional examples. Your actual Ledger and records stay unchanged.</Text>{STUDY_TOUR.map((t, i) => <LinkRow key={t.key} title={`${i + 1}. ${t.title}`} detail={t.task} name="arrow-forward-outline" onPress={() => jump(t.key)} />)}{onExit ? <Button quiet label="Exit design study" onPress={onExit} /> : null}</> : <><Text style={s.emptyTitle}>Performed facts first.</Text><Text style={s.bodyCopy}>Top load is what you lifted. A rep record is the highest performed load at that rep count. Estimated 1RM is a calculation with a source set, not a recorded single.</Text><Text style={s.bodyCopy}>The chart uses dated observations, labelled units and a numeric scale. Tap or drag to inspect a point. Variants and machine equipment contexts keep separate histories.</Text><Button quiet label="Return to the record" onPress={() => setSheet(null)} icon="arrow-back" /></>}</ScrollView></Vi