{h.sets} sets · {h.time}</Text>{h.record ? <View style={s.historySignal}><Icon name="trending-up" color={C.success} size={15} /><Text style={s.historySignalText}>{h.record.replace('170 kg', `${studyWeight(170, unit)} ${unit}`).replace('195 kg', `${studyWeight(195, unit)} ${unit}`).replace('180 kg', `${studyWeight(180, unit)} ${unit}`)}</Text></View> : null}</View></Pressable>) : <Empty icon="search-outline" title="No matching history." body="Try a movement name, a Session name or another date." />}</>}</>;

