yle={s.swatches}>{[C.canvas, C.panel, C.text, C.accent, C.success].map(color => <View key={color} style={[s.swatch, { backgroundColor: color }]} />)}</View><View style={s.noteRule} /><Eyebrow>RESEARCH, APPLIED</Eyebrow>{REFERENCES.map(r => <Pressable key={r.title} accessibilityRole="link" onPress={() => void Linking.openURL(r.url)} style={s.reference}><View style={s.spread}><Text style={s.referenceTitle}>{r.title}</Text><Icon name="arrow-up-right-box-outline" size={15} color={C.muted} /></View><Text style={s.caption}>{r.note}</Text></Pressable>)}<View style={s.noteRule} /><Button label="Next in the story" icon="arrow-forward" onPress={() => jump(STUDY_TOUR[(currentStep + 1) % STUDY_TOUR.length].key)} /></ScrollView></View></> : <>{!embedded ? <View style={s.mobileLabBar}><Text style={s.caption}>DEV design study · {Math.max(0, currentStep) + 1} / {STUDY_TOUR.length}</Text><Pressable onPress={() => jump(STUDY_TOUR[(currentStep + 1) % STUDY_TOUR.length].key)} accessibilityRole="button" accessibilityLabel="Next storyboard screen" style={s.mobileNext}><Text style={s.actionText}>Next</Text><Icon name="arrow-forward" size={17} /></Pressable></View> : null}{phone}</>}
